/* Preguntas candidatas a nuevas del PDF: filtro textual conservador, no garantía de unicidad clínica. Claves del PDF SIN VALIDACIÓN científica; sin calificación. */
EX.push(...[{"id":"pdf-novas-1","name":"PDF NOVAS · CIRUGÍA (PENDIENTES DE VALIDACIÓN)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"Pregunta 35 (UAI AGOSTO 2025) Una mujer de 68 años con antecedentes de diabetes tipo 2 y enfermedad vascular periférica se presenta con dolor abdominal súbito de intensidad 10/10. Niega diarrea o fiebre. El abdomen se palpa blando, sin signos peritoneales. Los ruidos hidroaéreos están presentes. Refiere que el dolor comenzó hace 4 horas, poco después de comer. Al laboratorio presenta: leucocitosis, lactato elevado y pH 7,29. cuál de las siguientes patologías se debe descartar prioritariamente en esta paciente?","o":["ISQUEMIA MESENTÉRICA AGUDA","Pancreatitis aguda.","Colecistitis aguda.","Apendicitis aguda"]},{"n":2,"q":"Un paciente colecistectomizado hace 10 años ingresa con un síndrome coledociano. La ecografía muestra vía biliar intrahepática levemente dilatada con imagen hiperecogénica en colédoco distal. ¿Cuál es el tratamiento más adecuado?","o":["Colangiografía endoscópica retrógrada y eventual papilotomia endoscópica.","Laparotomía exploradora y coledocotomia.","Extracción de lito a través del tubo de Kehr.","Laparotomía, coledocotomia y anastomosis biliodigestiva."]},{"n":3,"q":"Respecto a la cirugía de resección del adenocarcinoma de cabeza de páncreas señale cuál es la técnica más empleada: *","o":["La enucleación del tumor sin necesidad de linfadenectomía.","La pancreaticoyeyunostomía, que consiste en la derivación del ducto pancreático al intestino.","La duodenopancreatectomía cefálica con linfadenectomía regional.","La pancreatectomía corporo-caudal por laparoscopia."]},{"n":4,"q":"Se opera a un paciente de 65 años con diverticulitis colica perforada, practicándose una hemicolectomia izquierda más esplenectomía por desgarro capsular al 6º día postoperatorio presenta fiebre mantenida de 38°C, ligero enrojecimiento facial y oligura a pesar de sueroterapia correcta el día anterior tuvo tres deposiciones escasas y diarreicas, con abdomen ligeramente distenido, no doloroso, TA 150/85, pulso 85 latidos. ¿En cuál del siguiente proceso hay que pensar en primer lugar?","o":["Peritonitis aguda por contaminación operatorioa","Endocarditis infecciosa secundaria a diverticulits","Sepsis postesplenectomia","Dehiscencia anastomotica e iniciación de sepsis"]},{"n":5,"q":"cuál es el fundamento para infiltrar las heridas con anestesia local antes de la incisión quirúrgica aun cuando el paciente se encuentre con anestesia general? cirurgia general 2016,76","o":["Disminuir la hemorragia","Facilitar la disección de los planos","Profilaxis del dolor postoperatorio","Disminuir la descarga simpática para bloquear el aumento de la tensión arterial."]},{"n":6,"q":"una mujer de 76 acude a urgencia refiriendo dolor en ingle derecha y vomito desde hace unas 6 horas. a la exploración se palpa una tumoración de consistencia dura justo por debajo de la línea que une la espina ilíaca anterosuperior y el pubis (ligamento inguinal. ¿lo, más probable es que se trate de una?","o":["Hernia inguinal directa","Hérnia inguinal indirecta","Hérnia femora (crural)","Hérnia obturatriz"]},{"n":7,"q":"un paciente fue operado hace 20 dias por apendicitis flemonosa. egreso del hospital al tercer dia de um posoperatorio sin complicaciones aparentes. se le retiro al drenaje peritoneal instalado al terminar. regresa en el hospital (4 dia del alta) debido a que hace 3 dias presenta hipertermia en picos, con registro de 39 grados. el abdomen esta poco tenso. el dolor abdominal es sordo y leve, el tránsito intestinal se encuentra conservado. el cuadro humoral es de leucocitos polimorfo nucleares (20,000xmm) y la eritrosedimentacion se encuentra muy acelerada (80mm). cuál es el probable diagnostico?","o":["Sinusitis aguda","Peritonitis posoperatoria","Pielonefritis","Absceso subfrénico"]},{"n":8,"q":"al leer el resultado de una ecografía abdominal que usted ordeno por una infección urinaria a repetición comprueba que la mujer de 67 años tiene cálculos en la vesícula biliar. la paciente niega haber presentado cólicos o ninguna otra complicación relacionada con la colelitiasis. su única queja es la distención abdominal postprandial. ¿cual de las siguientes recomendaciones le dará usted?","o":["La distención postprandial indica que debe ser sometida a una colecistectomia de urgencia","No este indicado el tratamento quirurgico porque se trata de una colelitiasis asintomática","Debe ser sometida a un colecistectomía abierta y no laparoscópica para prevenir un cáncer de vesícula","La colecistectomía profiláctica está indicada por tratarse de una mujer"]},{"n":9,"q":"Si a un paciente en su valoración anestésica prequirúrgica le informan un asa tipo V:","o":["El paciente tiene un riesgo leve","El paciente tiene una enfermedad sistémica severa sin relación con la patología","El paciente esta moribundo y tiene pocas chances de sobrevida y la cirugía es su último recurso","El paciente tiene enfermedad sistémica severa que tiene relación con la patología"]}]},{"id":"pdf-novas-2","name":"PDF NOVAS · DIGESTIVO (PENDIENTES DE VALIDACIÓN)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"¿Cuál es el diagnóstico más probable de un paciente que tiene la siguiente serología: HBsAg (+) / HBsAC (-) / HBcAg (+)?","o":["Hepatitis B crónica.","Hepatitis B fulminante.","Huella de inmunización contra hepatitis","Hepatitis B aguda."]},{"n":2,"q":"¿Cuáles de estos marcadores clínicos en el momento del ingreso del paciente, predicen el desarrollo de pancreatitis aguda grave?","o":["Hematocrito mayor de 35.","IMC mayor de 25.","Alteración de la conciencia.","Edad mayor de 40 años."]},{"n":3,"q":"Un hombre de 43 años consulta por presentar dolor muy intenso de pocas horas de evolución, de instalación brusca, localizado en epigastrio e irradiado a la fosa ilíaca derecha. Tiene antecedentes de cirugía de rodilla reciente por lo que se encuentra medicado con DAINEs. El examen físico revela palidez, sudoración, taquicardia, discreta hipotensión arterial, abdomen tenso, no depresible con reacción peritoneal. ¿Cuál de los siguientes exámenes complementarios tiene mayor probabilidad de orientar un diagnóstico en esta situación? *","o":["Radiografía de tórax.","Determinación de hematocrito.","Recuento de glóbulos blancos.","Ecografía abdominal."]},{"n":4,"q":"Ramón, maestro de escuela primaria, lo consulta por cuadro de astenia, decaimiento y dolor abdominal en hipocondrio derecho de 4/10, acompañado de nauseas de un mes de evolución. Como antecedentes colecistectomia y dislipemia. Nos Cuenta muy avergonzado que toma vino, 1.5 litros por día y cerveza los fines de semana. Usted lo revisa y observa escleras ictéricas y hepatomegalia dolorosa. Pide un laboratorio: TGP 240 U/L, TGO 125 U/L, Fosfatasa alcalina 180, Bilirrubina total 2.3, BD 1.8, eritrosedimentación 32 y recuento de blancos 8200 con fórmula conservada. Su primer diagnóstico es:","o":["Hepatitis alcohólica.","Cirrosis hepática avanzada.","Insuficiencia hepática severa","Hepatitis viral"]},{"n":5,"q":"un paciente de 78 años se encuentra en el séptimo día de internación por un acv isquémico, presenta distención abdominal marcada y desde hace 3 días catarsis negativa. al examen físico se constata que el abdomen se encuentra doloroso de manera difusa, sin reacción peritoneal y los rha son negativos. no elimina gases. se realiza radiografía de abdomen que muestra dilatación del colon generalizada, que es más pronunciada desde el ciego hasta el ángulo esplénico. ¿según su sospecha diagnostica, cual es la conducta más adecuada?","o":["Cecostomia guiada por imagenes","Descompresion por videocolonoscopia","Laparatomia exploradora","Hemicolectomia derecha"]},{"n":6,"q":"mujer de 88 años, diagnosticada de un adenocarcinoma de Colón con metástasis hepática. acude a la consulta 3 semanas después del diagnóstico con estreñimiento de 3 días de evolución, sin náuseas ni vómitos. a las exploraciones clínicas es blando, depresible y ruidos presentes. la paciente toma 20 mg/día de cloruro de mórfico. desde el diagnóstico, con dolor abdominal controlado. cual considera que es la actitud terapéutica más indicada?","o":["Bajar dosis de opioides a la mitad","Pautar un laxante osmótico y comprobar mediante un tacto rectal que exista impactación fetal","Pautar un procinético","Realizar una tc urgente, ante la sospecha de obstrucción intestinal"]},{"n":7,"q":"ante la sospecha clínica de sobrecrecimiento bacteriano intestinal. todas las siguientes afirmaciones son correctas, excepto:","o":["La biopsia es la prueba diagnóstica","Presencia de anemia","Antecedentes de cirurgia gastrointestinal","Presencia de diarreia"]},{"n":8,"q":"joven de 18 años, con antecedentes de asma, alergia a pólenes, ácaros y pelo de gato, acude a urgencia e refiriendo sensación de detención de alimento a nivel retroexternal con practica incapacidad para deglutir su propia saliva. refiere episodios similares en otras ocasiones, que han cedido de forma espontanea en pocos min. cual de los siguientes es el dx más probable.","o":["Esófago de barret","Anillo esofágico distal (schaztki)","Esofagitis infecciona","Esofagitis eosinofilica"]},{"n":9,"q":"un paciente ingresa con dx hda, en situación hemodinámica estable. se realiza una veda que informa: lesión ulcerada en cara posterior del bulbo duodenal con hemorragia activa no pulsátil, Forrest: ib. se practica esclerosis endoscopia con adrenalina consiguiéndose hemostasia. señala la afirmación correcta:","o":["La lesión descrita tiene un riesgo bajo de recidiva hemorrágica.","En caso de recidiva hemorrágica, es imprescindible la intervención qx","Por la localización de la lesión puede estar afectada la arteria gastroduodenal","En caso de intervención qx es obligatoria la práctica de una vagotomía troncular"]},{"n":10,"q":"cuál de los siguientes rasgos morfológicos no esperamos encontrar en una biopsia de cuerpo gástrico de un paciente con deficiencia de vitamina B12?","o":["H. Pylori","Metaplasia intestinal","Hiperplasia de células endocrinas","Atrofia"]},{"n":11,"q":"Una mujer de 60 años, postmenopáusica, consulta por astenia y disnea de esfuerzo asociada a pirosis ocasional. En la videoendoscopía digestiva alta se observa una pequeña hernia hiatal por deslizamiento sin signos de esofagitis y tiene los siguientes estudios hematológicos: hemoglobina 8 gr%, VCM 69 fl (80-100 fl), ferremia 13 mcg/dl, ferritina 4 ngr/ml. ¿Cuál es la conducta más adecuada?","o":["Indicar tratamiento con hierro oral y reevaluar en tres meses.","Indicar tratamiento con inhibidores de la bomba de protones y reevaluar en un mes.","Solicitar un estudio con capsula endoscópica.","Solicitar una videocolonoscopia"]},{"n":12,"q":"¿Cuál es la etiología más frecuente de la dispepsia?","o":["Consumo crónico de alcohol","Ulcera péptica","Funcional","Consumo crónico de AINEs"]},{"n":13,"q":"¿Cuál es el mecanismo de acción del laxante PEG (polietilenglicol)?","o":["Formador de masa","Estimulante","Lubricante","Osmótico"]}]},{"id":"pdf-novas-3","name":"PDF NOVAS · EMERGENTOLOGÍA (PENDIENTES DE VALIDACIÓN)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"En un traumatismo cráneo facial, cuando está contraindicado la colocación de sonda nasogástrica?","o":["Fractura de base de cráneo","Fractura de orbita y de la rama ascendente del maxilar inferior","Hemorragia nasal","Fractura del piso de orbita"]},{"n":2,"q":"Ante la sospecha de deglución de un cuerpo extraño, debe realizarse inmediatamente, además de la anamnesis y la rinoscopia","o":["Abundante ingestión de liquido","Administración de espasmolíticos","Esofagoscopia","Radiografía lateral de cuello y superior de tórax"]},{"n":3,"q":"las intervenciones que contribuyen al éxito tras una parada cardiaca ocurrida en la calle se denominan “cadena de supervivencia”. ¿cuáles de las siguientes opciones conforman el orden adecuado de sus estabones?","o":["Desfibrilación inmediata pedir ayuda maniobras de soporte vital cuidados post resucitación","Abrir la via aerea pedir ayuda desfribilacion cuidados post resucitacion","ventilación boca a boca compresiones toracicas intermitentes desfibrilacion solicitar ayuda cuidados post resucitacion","Reconocimiento precoz y pedir ayuda, resucitacion cardiopulmonar precoz desfibrilacion precoz cuidados post resucitación"]},{"n":4,"q":"una joven de 24 años sufre una caída de la bicicleta con traumatismo en la zona abdominal con el manillar. a las pocas horas del traumatismo, comienza con dolor intenso en hipocondrio izq, por lo que acude a consultar a un servicio de urgencias. a su llegada, el paciente se encuentra pálida y sudorosa, la ta: 82/54 mmhg, fc: 120. qué tipo de choque es el más probable.","o":["Hipovolémico","Séptico","Cardiogénico","Neurogénico"]},{"n":5,"q":"con respecto de las quemaduras que manifestaciones clínicas presentan las quemaduras de segundo grado?","o":["Superficie dura, formación de ampollas y exudado","Dolor intenso, formación de ampollas y exudado","Dolor escaso o ausente, exudado y ampollas","Eritema, dolor a superficie costrosa y seca"]},{"n":6,"q":"Ud. está realizando compresiones torácicas a una víctima adulta de paro cardíaco. ¿Cuál de las siguientes es la frecuencia correcta a la que debe realizar las compresiones durante el RCP de un adulto?","o":["100/150 veces por minuto.","100/120 veces por minuto.","100/80 veces por minuto.","100/60 veces por minuto"]},{"n":7,"q":"De acuerdo al orden establecido basado en el riesgo de muerte del paciente, ¿Cuál es la correcta valoración inicial de un paciente politraumatizado? (único 2019)","o":["Protección de la vía aérea y columna cervical; circulación; daño neurológico, respiración y exposición y control ambiental.","Respiración; circulación; control de vía aérea y columna cervical; neurológico, exposición y control ambiental.","Protección de la vía aérea y columna cervical; respiración; circulación; daño neurológico; exposición y control ambiental.","Respiración; exposición y control ambiental; circulación; protección de la vía aérea y columna cervical; daño neurológico"]}]},{"id":"pdf-novas-4","name":"PDF NOVAS · GINECOLOGÍA Y OBSTETRICIA (PENDIENTES DE VALIDACIÓN)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"pregunta 90 que signo es considerado de severidad, ante diagnóstico de preeclampsia?","o":["disminución de plaquetas por debajo de 100.000/mm","edema en miembros inferiores.","proteinuria de 1+.","presión arterial de 140/90 mmhg."]},{"n":2,"q":"pregunta 91 paciente de 22 años, estudiante universitaria, acude por a un médico generalista por presentar irregularidades menstruales de 3 años de evolución. refiere ciclos menstruales cada 45-60 dias, con escaso sangrado. imc 29, acné moderado en cara y espalda. ¿cuál de los siguientes estudios complementarios considera que tendrá mayor valor diagnóstico?","o":["ecografía de tiroides","ecografía transvaginal (sop)","medición de hormonas tiroideas","tac de abdomen"]},{"n":3,"q":"pregunta 94 gestante de 34 semanas con rotura de membrana de 16 horas de evolución. presenta fiebre 38.5, taquicardia materna, dolor ¿intestinal? y mal olor en el flujo vaginal. ¿cuál es la conducta indicada?","o":["iniciar antibióticos de amplio espectro e interrumpir embarazo","solo iniciar antibióticos.","observación estrecha y control de temperatura.","indicar cesárea urgente"]},{"n":4,"q":"pregunta 96 mujer de 38 años, nulípara, consulta por sangrado uterino abundante e irregular. ecografía útero aumentado de tamaño con múltiples miomas intramurales. el mayor de 5 cm. desea conservar fertilidad. ¿cuál es el tratamiento más adecuado?","o":["miomectomía conservadora","histerectomía.","embolización de las arterias uterinas.","agonistas de la gnrh"]},{"n":5,"q":"Una paciente de 62 años, postmenopáusica, consulta por metrorragia. Como antecedente relevante la paciente refiere cáncer de mama, por el que realizó tratamiento conservador hace 2 años y actualmente está tomando tamoxifeno. La paciente se encuentra libre de enfermedad. La ecografía transvaginal informa útero AVF 45x40x38 mm (DLxDAPxDT), endometrio quístico de 18 mm espesor, anexos sin particularidades. ¿Cuál es la conducta más adecuada?","o":["Histeroscopía.","Anexohisterectomía total.","Control habitual.","Legrado endocervical."]},{"n":6,"q":"A una mujer de 23 años se le realiza diagnóstico de epilepsisa. Se encuentra en tratamiento con anticonceptivos orales para regular los ciclos menstruales. ¿Cuál es el fármaco antiepiléptico recomendado en este caso? *municipalidad 2016/30","o":["Carbamazepina.","Fenobarbital.","Levetiracetam.","Ácido valproico."]},{"n":7,"q":"Usted asiste una embarazada de 34 semanas internada por preeclampsia grave y recibe los resultados de laboratorio de control: hematocrito 32%, hemoglobina 10,8 gr/dl, TGO 115 UI/L, TGP 145 UI/L, Uricemia 4,8 mg/dl, Uremia 35 mg/dl, 0.8 mg/dl, Plaquetas 85000/mm3, LDH 650 ui/l, Proteinuria 1500 mg/24 horas. En función de estos resultados, ¿cuál es su presunción diagnóstica? *","o":["Preeclampsia grave.","Síndrome HELLP.","Preeclampsia leve.","Hipertensión inducida por el embarazo con síndrome urémico-hemolítico."]},{"n":8,"q":"Cuál es la causa patológica más frecuente de hemorragia de la segunda mitad del embarazo?","o":["Rotura uterina.","Desprendimiento de placenta.","Vasa previa.","Placenta previa."]},{"n":9,"q":"Qué estudios serológicos solicita en la rutina del primer control prenatal? *","o":["VIH, Hepatitis B, Rubeola, Chagas Y Toxo.","VDRL, VIH, Toxo, Chagas, Hepatitis B.","VDRL, Toxo, Hepatitis B, Rubeola y VIH.","VDRL, Chagas, Hepatitis C, Hepatitis B y Rubeola."]},{"n":10,"q":"Qué maniobra semiológica se utiliza para el diagnóstico de situación fetal?","o":["Leopold 3","Leopold 2","Leopold 4","Leopold 1"]},{"n":11,"q":"Usted se encuentra asistiendo el trabajo de parto de una mujer embarazada de término con antecedente de 1 cesárea previa. Al examen la paciente presenta 1 contracción cada 3 minutos de 45 segundo de duración, tono uterino normal, frecuencia cardiaca fetal 135 latidos por minuto, con 6 cm de dilatación. Súbitamente, la paciente refiere intenso dolor suprapúbico, y se aprecia un sangrado regular por genitales externos. Usted realiza palpación abdominal, pudiendo palpar la tensión y dolor de ambos ligamentos redondos. ¿Cuál es su presunción diagnóstica? *","o":["Rotura de vasa previa","Dehiscencia de cicatriz anterior","Rotura de seno marginal","Desprendimiento prematuro de placenta normoinserta"]},{"n":12,"q":"Usted se encuentra evaluando la maduración pulmonar del producto de la concepción de una mujer que cursa un embarazo de riesgo. Al realizar la amniocentesis, se observa que el líquido obtenido está contaminado con sangre materna. ¿Qué prueba debe realizarse?","o":["Cociente de lecitina-esfingomielina","Fosfatidilglicerol","Test de Clements","Estudio citológico"]},{"n":13,"q":"Una paciente de 50 años consulta porque quiere hacerse un control periódico de salud. ¿Cuál de los siguientes métodos complementarios de diagnóstico NO forma parte del Screening recomendado para este paciente?","o":["Papanicolau","Fibrocolonoscopia","Colesterolemia","Ecografía ginecologíca"]},{"n":14,"q":"Cuales de los siguientes son los motivos de consulta más frecuentes de una paciente que padece endometriosis?","o":["Esterilidad, Dispareunia, disuria","Dolor pelviano, esterilidad, dismenorrea","Dismenorrea, tenesmo rectal, dolor pelviano","Tumoración anexial, síndrome anémico, menometrorragia"]},{"n":15,"q":"Cuál de las siguientes condiciones NO es categoría 4 de los criterios de elegibilidad de la OMS para los anticonceptivos combinados? (ACO)","o":["Hipertensión moderada o severo","Fumadora de, más de 20 cigarrillos menos de 35 anos (más de 35 anos es criterio).","Migraña con síntomas neurológicos","Diabetes con complicaciones vasculares"]},{"n":16,"q":"Una paciente de 65 años concurre a control ginecológico adjuntando ecografía que informa: útero en anteversoflexión de 60x42x38 mm, endometrio 3 mm homogéneo, ovario derecho 15x16 mm, ovario izquierdo reemplazado por formación quística de 60x55 mm con presencia de una proyección papilar de 5mm. En base a su diagnóstico más probable, ¿cuál es la conducta más adecuada?","o":["Solicitar tomografía axial computada.","Solicitar CA125, CEA y Doppler color.","Solicitar CA125 y realizar tratamiento quirúrgico.","Realizar nueva ecografía en 3 meses"]},{"n":17,"q":"Un embarazo que presenta muerte fetal en la segunda mitad del embarazo, cuál es la complicación materna más grave:","o":["Hemorragia genital.","Coagulación intravascular.","Infección.","Eclampsia"]},{"n":18,"q":"¿Cuál de los siguientes tipos del virus papiloma humano (VPH) es responsable de la mayor porción de carcinoma de cuello uterino?","o":["6 y 11.","16 y 18.","40 y 42.","54 y 61."]},{"n":19,"q":"Lo consulta una mujer de 40 años que presenta derrame por el pezón. Luego de realizarle el examen usted determina que es unilateral, uniporo, sanguinolento y espontaneo. Tiene como antecedente, una lactancia durante un corto periodo, debido a alteraciones emocionales postparto y que fue inhibida farmacológicamente. No tiene antecedentes familiares de patología mamaria. ¿Cuál de las siguientes opciones es CORRECTA de acuerdo al resultado del estudio citológico del derrame?","o":["Si es negativo para células atípicas descarta la existencia de un carcinoma y no toma ninguna conducta.","Si es negativo para células atípicas no descarta la posibilidad de un carcinoma y continúa con los estudios de la paciente","Si es positivo para células atípicas implementa un tratamiento quirúrgico amplio sabiendo que el 4-5% de los cánceres de mama producen derrame por el Pezón.","Si es positivo para células atípicas indica radioterapia en volumen mamario e investiga secundarismo."]},{"n":20,"q":"Una mujer de 28 años de edad lo consulta como médico clínico. Es hipertensa, tratada con enalapril, y ante la sospecha de un embarazo le solicitaron un dosaje de subunidad beta de la gonadotrofina coriónica que fue positivo. ¿Cuál es la conducta a seguir con respecto a su medicación antihipertensiva?","o":["Suspender el enalapril y administrar metildopa","Esperar con la misma medicación hasta que consulte con su obstetra","Continuar con enalapril y agregar un diurético","Suspender el enalapril y sólo administrar un fármaco antihipertensivo si la presión arterial sistólica supera los 155 mm Hg"]},{"n":21,"q":"Una paciente de 25 años concurre a la consulta ginecológica porque desea comenzar a utilizar Anticonceptivos Orales (ACO). Según la Guía “Métodos anticonceptivos guía práctica para profesionales de la salud” Ministerio de Salud de la Nación. Agosto 2014. ¿Cuáles son las prácticas mínimas para iniciar tratamiento con ACO? (MUNI 2017/46)","o":["Toma de papanicolaou y solicitar laboratorio con enzimas hepáticas.","Toma de Presión Arterial.","Toma de Presión Arterial y solicitar laboratorio y ecografía transvaginal.","Toma de Papanicolaou."]},{"n":22,"q":"cuál es la conducta más adecuada con una mujer de 25 años que consulta por aumento del flujo vaginal en las últimas semanas y su pareja presenta secreción ureteral, pero no quiere consultar? utiliza anticonceptivos orales combinados. en el examen físico el abdomen es blando no doloroso en el examen ginecológico no tiene dolor y presenta abundante flujo purulento saliendo por el orificio cervical externo. único 2017- 23","o":["Indicar tratamiento con metronidazol ambos.","Cultivo de secreción cervical y citar en 48 horas con la pareja para iniciar tratamiento según resultados.","Solicita ecografía urgente para definir internación, tratamiento empírico con ceftriaxona y doxiciclina a ambos.","Cultivo de secreción cervical, tratamiento con ceftriaxoma azitromicina a ambos."]},{"n":23,"q":"cuál de los siguientes estudios solicitaría una paciente de 40 años, obesa, sin antecedentes patológicos, que fue tratada hace un mes por candidiasis vaginal y que ahora nuevamente presenta el mismo cuadro? la paciente realizó tratamiento con óvulos vaginales con antimicóticos en forma adecuada y no recibió ningún otro tratamiento. unico 2017,35","o":["Orina completa.","Hormonas tiroideas.","Glucemia.","Hemograma."]},{"n":24,"q":"mujer de 16 años que consulta por amenorrea primaria. presenta un desarrollo femenino o normal de los caracteres sexuales secundarios. los niveles de estradiol y testosterona son normales. en la exploración ginecológica se aprecia agenesia de vagina. se realiza ecografía y se aprecia ausencia de útero. los ovarios son normales ecográficamente. no se observa riñón izquierdo. ¿el diagnostico, más probable?","o":["Síndrome de rokitanski","Síndrome de morris","Hiperplasia suprarrenal congénita","Síndrome de ovarios poliquísticos"]},{"n":25,"q":"Los efectos anticonceptivos secundarias del componente progestacional em los anticonceptivos orales de combinacion incluyen.","o":["Alteraciones endometriales, disminuicion em la viscosidad del moco cervical","Alteraciones endometriales, aumento em la viscosidad del moco cervical","Estimulo de la produccion endogena de estrogenos","Aumento en la viscosidad del como cervical, estimulo de la producción del estrógeno endógenos."]},{"n":26,"q":"una paciente de 23 años consulta por dolor pelviano, flujo genital y fiebre. tiene colocado un dispositivo intrauterino (diu) como método anticonceptivo. presenta 38 de temp axilar y en el examen ginecológico se tacta el útero y anexo derechos dolorosos. ¿cuál es la conducta más adecuada en esta paciente?","o":["Extracción del diu, indicación de óvulos y control en 48 hs","Toma de cultivo endocervical, extracción del diu, indicación de una monodosis de cefalosporina de 3ra generación más doxiciclina por 10 días y control en 48 hs","Toma de cultivo endocervical y hemocultivos e indicacion de tratamiento antibiótico de acuerdo al resultado de los cultivos","Toma de cultivo endocervical extracción del diu, indicación de analgésicos y antiinflamatorios no esteroides y control en 48 horas."]},{"n":27,"q":"una paciente de 29 años com esterilidad primaria de 7 meses de evolución consulta por dismenorrea que comenzó 2 años atrás y se intensifico en los meses. adjunta en ecografía transvaginal que informa imagen quística com contenido finamente particulado en ovario derecho de 7 cm de diámetro y ca 125 de 50 u/ml. en base al diagnóstico presuntivo. ¿cuál es la conducta más adecuada?","o":["Indicar anticonceptivos orales y control en 6 meses","Tratamiento medico","Laparoscopia diagnóstica y terapéutica","Anexectomia derecha"]},{"n":28,"q":"mujer de 40 semanas de gestación en trabajo de parto con 6 cm de dilatación. presenta patrón fetal decelerativo registro cardiotocografico por lo que se decide realizar microtoma de sangre fetal para valorar bienestar fetal. resulta ph 7,22. la conducta correcta es?","o":["Acidosis grave, cesárea urgente","Valor prepatologico, repetir toma en 15- 20 minutos","Acidosis moderada, repetir toma en 1-2 horas","Repetir en el momento, posible error en la obtención de la toma"]},{"n":29,"q":"recién nascido de 2 horas de vida inicia rechazo de alimento, llanto constante y febrícula por lo que es llevado a la sala de terapia de neonatología del hospital. al ingreso se constata leve ictericia, hepatoesplenomegalia y lesiones en periorificios. la madre dice que le administraron tratamiento para sífilis por boca en el embarazo, porque era alérgica a la penicilina. le realizaron vdrl a la madre, que es informada como positiva en 1/128 diss. ¿cuál es su conducta?","o":["Se solicita una vdrl al bebe de urgencia y si da negativo descarto sífilis congénita. realizo curva de vdrl en él bebe y busco otras causas.","Se solicita vdrl y si es positiva es diag. de certeza de sífilis congénita. le adm penicilina benzatinica 2,4 millones de ui 1 vez a la semana por via im.","Realizo fondo oscuro de lesiones periorificiales y si son positivas es diagnóstico de certeza de sífilis congénita adm penicilina g sódica 300.000 ui/día ev por 10 a 15 días.","Se solicita vdrl y ftabs al bebe, si da positivo ambos estudios el bebe está infectado le adm eritromicina ev al bebe porque la madre es alergica a la penicilina"]},{"n":30,"q":"una mujer de 26 años acude a la guardia por dolor abdominal y escasa perdida hemática por vagina. refiere amenorrea de 7 semanas. le realiza un teste de embarazo con resultado positivo. ¿cual es el siguiente paso?","o":["Realizar un examen ecográfico vaginal","Evaluar el útero mediante legrado por aspiración","Pautar progesterona natural micronizada por vía vaginal hasta la semana 14 de gestación","Evaluar el útero mediante la adm intravaginal de prostaglandinas"]},{"n":31,"q":"Señale la correcta con respecto al siguiente enunciado: La vagina esta irrigada por la arteria…","o":["Cérvico –vaginal rama de la hemorroidal media","Vésico – vaginal rama de la Hipogástrica","Vaginal inferior rama de la femoral","Cérvico – vaginal rama de la iliaca externa"]},{"n":32,"q":"Marta de 60 años le consulta por flujo vaginal blanquecino como leche cortada de 4 dias de evolucion, acompañado de disuria y prurito vaginal, esta es la cuarta vez en el año que presenta este flujo. Es obesa y dbt. ¿Cual es la conducta a seguir?","o":["indicar clotrimazol local por 7 dias mas fluconazol por 3 dias vo","indicar fluco local x 3 dias mas 1 por semana por 3 meses","indicar clotri local por 14 dias mas fluco vo x 3 meses","clotri local x 7 dias mas fluco oral x 6 meses 172"]}]},{"id":"pdf-novas-5","name":"PDF NOVAS · HEMATOLOGÍA (PENDIENTES DE VALIDACIÓN)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"¿Cuál de las siguientes anemias es habitualmente macrocítica?","o":["Anemias sideroblásticas.","Anemias ferropenica.","Anemias por déficit de ácido fólico.","Talasemias."]},{"n":2,"q":"En un hemograma la anisocitosis aparece cuando aumenta?","o":["HCM","RDW","Hematocrito","VCM"]},{"n":3,"q":"Paciente gue lo consulta luego de varias visitas a diferentes médicos. Le cuenta su sintomatología, tú lo examina y le pide laboratorio. Llega al diagnóstico de vasculitis, en cuanto a las vasculitis marque la afirmación correcta:","o":["La enfermedad de Takayasu es de los pequeños vasos.","La enfermedad de Wegener se caracteriza por afectación de pulmón riñón.","Vasculitis por hipersensibilidad se caracteriza por afectación visceral importante","Vasculitis granulomatosa de ChurgStrauss. Se caracteriza por la disminución de los eosinófilos"]},{"n":4,"q":"Acude a la consulta un hombre de 67 años que refiere ligera astenia desde hace 2 meses y una pérdida de peso de 6kg en el mismo plazo. No refiere fiebre, cambios en el habito deposiciones ni síndrome miccional. En la exploración física únicamente destacan: soplo sistólico panfocal 2/4 y hepatomegalia no dolorosa a través de dedo en línea medioclavicular. Aporta la siguiente analítica: hemograma: HB: 7,9g/dl; HTO: 22%; VCM: 75fl; Leucocitos 8.800/picolitros (PMN: 63%; LINFOCITOS: 22%; MONOCITOS: 12%; EOSINOFILOS: 3%), Plaquetas 550.000. Bioquímica: Creatinina: 0,89; Glucosa: 112mg/dl; Sodio 142; potasio 4,2; Cloro 100; GOT 16; GPT 21; GGT 71; LDH 88; Bilirrubina 0,91; Sideremia 21; Ferritina 12; TIBC 450. ¿La actitud más adecuada seria? (MIR 2008/09 p114)","o":["Transfundir 2 concentrados de hematíes. Posteriormente comenzar tto con hierro oral durante 6 meses.","Transfundir 2 concentrados de hematíes. Solicitar panendoscopia oral y colonoscopia.","Iniciar tto con hierro oral. Solicitar panendoscopia y colonoscopia, suspendiendo ferro terapia 10 dias antes de la colonoscopia. Reanudar la ferroterapia y mantener por 6 meses hasta corregir la anemia.","Iniciar tto con hierro oral. Solicitar panendoscopia y colonoscopia, suspender la ferroterapia 10 dias antes de la colonoscopia. Reanudar la ferroterapia y mantenerla hasta corregir la anemia."]},{"n":5,"q":"paciente de 35 años que debido a hematemesis por ulcera duodenal sangrando recebe una transfusión de concentrado de glóbulos rojos, a los 5-10 min de iniciarse la transfusión comienza con fiebre, escalofrío, hipotensión, dolor en región lumbar. cuál sería el dx más probable.","o":["Contaminación bacteriana de la sangre","Reacción febril secundaria a la transfusión","Reacción febril por el plasma que contamina los hematíes.","Reacción transfusional hemolítica"]},{"n":6,"q":"paciente de 45 anõs que acude a urgencia por malestar general, cefalea e cansancio progresivo en las últimas semanas. a la exploración física se detecta un ligero tinte ictérico de piel y mucosas y se palpa esplenomegalia 2 cm bajo el reborde costal. la analítica presenta hemoglobina de 8,6 vcm: 100. la cifra de reticulocitos esta elevada en los frotes de sangre se observa anisopoiquilocitosis. en la bioquímica destaca, ldh: 1300, bilirrubina: 2,2 haptoglobina: indetectable. que prueba es la más apropiada para orientar el dx de la paciente?","o":["Test de sangre oculto en heces","Test de coombs","Determinación de hierro, colabamina y ac fólico","Aspirado de medula ósea"]},{"n":7,"q":"el prurito es una manifestación típica de todas las enfermedades salvo:","o":["Linfoma de hodgkin","Micosis fungoide","Mastositosis sistémica","Leucemia aguda mieloblástica"]}]},{"id":"pdf-novas-6","name":"PDF NOVAS · INFECTOLOGÍA (PENDIENTES DE VALIDACIÓN)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"Un varón de 45 años se encuentra en lista de programación de cirugía electiva abdominal. Tiene carnet con vacunación antitetánica completa y un refuerzo a los 27 años. No recuerda si luego se aplicó otro refuerzo. ¿Cuál es la indicación de profilaxis prequirúrgica que debe indicar?","o":["Ninguna, es suficiente la cobertura.","Vacunar con una dosis de toxoide, mínimo 15 días antes de la cirugía.","Indicar toxoide e inmunoglobulina en el prequirúrgico inmediato.","Indicar inmunoglobulina en el prequirúrgico inmediato."]},{"n":2,"q":"En un paciente con varicela, ¿cuál de estas medidas es más adecuada para evitar la sobreinfección bacteriana? *","o":["Administración de aciclovir VO.","Lavar la ropa con agua hirviendo.","Administración de antihistamínicos VO.","Evitar bañar al paciente."]},{"n":3,"q":"Un hombre de 38 años consulta por presentar, cuatro horas después de la ingesta de un helado, un cuadro de vómitos y deposiciones diarreicas sin sangre ni fiebre, Mientras que el paciente es Visitado por el medico de emergencias, su esposa inicia un cuadro similar. ¿Cuál de los siguientes microorganismos es probablemente el responsable del cuadro clínico?","o":["Salmonella enteriditis.","Sthaphylococus aureus","Shigella","Coli"]},{"n":4,"q":"Usted está realizando el control prenatal de una mujer de 25 años, primigesta, que se scree 18 de embarazo y no presenta antecedentes patológicos de importancia. La mujer refiere que hace una semana almorzó con la familia y hoy le avisaron que su sobrino tiene varicela. Al interrogatorio la paciente no está segura de haber tenido la enfermedad en la infancia, y actualmente se encuentra asintomática. Según la “Guía de Prevención y Tratamiento de las Infecciones Congénitas y Perinatales”, Ministerio de Salud de la Nación, 2010, ¿cuál es la conducta más adecuada en relación con la profilaxis? (muni2018/32)","o":["Solicitar serología IgG pareada y al confirmar el negativo indicar profilaxis con Aciclovir.","Solicitar serología IgG urgente y al confirmar el negativo indicar profilaxis con Aciclovir.","Solicita serología IgG pareada y al confirmar el negativo indicar profilaxis con Gammaglobulina.","Solicitar serología IgG urgente y al confirmar el negativo indicar profilaxis con Gammaglobulina."]},{"n":5,"q":"cual es el reservorio, de salmonella typhi a en una persona portadora?","o":["Los divertículos del colón","Vesícula biliar","Intestino delgado","Intestino grueso"]},{"n":6,"q":"ante un paciente con sepse por catéter por hemocultivo, positivo para estafilococos aureus meticelino resistente. cual antibiótico elige para el tto","o":["Cefalotina + gentamicina","Imipinen","Ampicilina + sulbactan","Vancomicina"]},{"n":7,"q":"un paciente acude su médico por presentar una secreción matinal uretral de aspecto purulento desde hace unas dos semanas. en el momento que lo atienden, no tiene secreción y el paciente si niega a que se le tome ninguna amuestra intrauretral. cuál de los siguientes tto considera el más adecuado?","o":["Penicilina benzatina + doxiciclina","Cefitraxona + doxiciclina","Espectnomicina + clindamicina","Cefixima + metronidazol"]},{"n":8,"q":"entre los siguientes fluidos corporales sin contenido hemoptoico, ¿cuál de ellos no se considera potencial infeccioso para la transmisión del VIH?","o":["Líquido cefalorraquídeo","Secreciones vaginales","Orina","Liquido pleural"]},{"n":9,"q":"Paciente de 48 años que consulta por un cuadro de fiebre, cefalea frontal intensa y sensación nauseosa de 48 horas de evolución. A la exploración física presenta un estado general conservado. No tiene lesiones cutáneas. Se aprecia una discreta rigidez de nuca con signo de Kenig positivo. Ante la sospecha de meningitis se practica una punción lumbar que da salida a un líquido de aspecto claro, con proteínas 170 mg/dl, glucosa 54 mg/dl (glucosa plasmática 98 mg/dl) y células 280 com un 89% de linfocitos. ADA 4 Ul/L. ¿Cuál es la causa más probable de la meningitis de este paciente?:","o":["Neisseria meningitis.","Mycobacterium Tuberculosis.","Streptococcus pneumoniae.","Enterovirus"]},{"n":10,"q":"Una paciente de 22 años consulta por presentar una lesión genital. Al examen físico se evidencia una úlcera indurada no dolorosa en región vulvar. Ante la sospecha de sífilis, respecto de la notificación de este caso, ¿cuál es la conducta más adecuada?","o":["Solicita pruebas de laboratorio para confirmar el caso y luego notificarlo.","Notifica sífilis temprana.","Notifica sífilis sin especificar.","Notifica control serológico sífilis"]},{"n":11,"q":"¿Cuál de las siguientes entidades no es responsable de meningitis a líquido claro?","o":["Neoplasias.","Viral","VIH.","Meningocócica"]},{"n":12,"q":"Cuál es la diferencia más significativa entre la vacuna conjugada 13-valente contra neumococo en comparación con la vacuna polisacárida 23-valente (PPSV23)? (UBA 2018)","o":["Tiene más efectos adversos locales","Es menos inmunógena en pacientes inmunodeprimidos","Genera una respuesta dependiente de linfocitos T que es más duradera (memoria inmunológica a largo plazo)","Son similares pero su costo es menor"]},{"n":13,"q":"¿Cuál es la lesión elemental que mejor caracteriza a la erisipela?","o":["Placas eritematodescamativas de límites netos con signos de flogosis","Placa eritematoedematosa de límites imprecisos con signos de flogosis","Placas eritematodescamativas de límites imprecisos con signos de flogosis","Placa eritematoedematosa de límites netos con signos de flogosis"]},{"n":14,"q":"¿Cuál de las siguientes es la tríada clásica de presentación clínica del síndrome mononucleosiforme?","o":["Fiebre, exantema y linfadenopatías","Fiebre, hepatomegalia y linfadenopatías","Faringoamigdalitis, fiebre y linfadenopatías","Faringoamigdalitis, hepatoesplenomegalia y linfadenopatías"]},{"n":15,"q":"En un paciente que consulta por adenopatías, ¿Qué región ganglionar consideras patológica si hallas adenomegalias en el examen físico?","o":["Región supraclavicular","Región preauricular","Región axilar","Región inguinal"]}]},{"id":"pdf-novas-7","name":"PDF NOVAS · NEUROLOGÍA (PENDIENTES DE VALIDACIÓN)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"Concurre a la guardia un paciente de 40 anos derivado de otro nosocomio para estudio por presentar debilidad y impotencia funcional de ambos miembros inferiores de varios meses de evolución. Al examen físico usted constata: atrofia muscular marcada, fasciculaciones, hipotonía muscular y hiporreflexia. Cuál es su diagnóstico presuntivo¿(único 2023)","o":["Síndrome motoneurona superior","Síndrome de polineuropatía desmielinizante inflamatoria crónica (CIDP)","Síndrome de motoneurona inferior","Esclerosis múltiple"]},{"n":2,"q":"Una paciente de 54 años es traída a la consulta por su marido, quien nos refiere que hace un mes ha comenzado a hablar incesantemente perdiendo a veces la idea directriz. Duerme 4 horas en total al día, muestra una intolerancia importante a las críticas y tiene conductas de riesgo físico que antes no tenía. Usted hace salir al marido y ella le manifiesta no haberse sentido mejor en su vida y que piensa en separarse de él. Planea construir una casa de fin de semana en un terreno, aunque no posee el dinero suficiente para esto, ni los medios para procurárselo. Su examen clínico es normal y no consume sustancias estimulantes. ¿Cuál es el diagnóstico más probable? (ÚNICO 2017,16)","o":["Trastorno de ansiedad generalizada.","Trastorno histriónico de la personalidad.","Esquizofrenia tipo desorganizado.","Episodio maníaco."]},{"n":3,"q":"en el diagnóstico diferencial entre paranoia y esquizofrenia es falso que:","o":["Los temas persecutorios aparecen en ambas entidades","El delirio es más comprensible en la paranoia","El yo esta más desestructurado en la esquizofrenia","Ambas entidades aparecen clasicamente en las mismas edades"]},{"n":4,"q":"¿Cuál es la conducta más adecuada con un varón de 60 años que consulta por cefalea intensa, visión borrosa y mareos de 6 horas de evolución, que se encuentra lúcido, sin signos de foco motor, sensitivo o meníngeo y tiene una tensión arterial de 220/110 mmHg?","o":["TAC de encéfalo sin contraste","Punción lumbar","Fondo de ojo (me parece la más adecuada).","Reposo y observación en guardia"]},{"n":5,"q":"Los núcleos parasimpáticos del facial son: (UBA 2019)","o":["Salivar inferior y lagrimal","Salivar superior y lagrimal","Salivar inferior y de Edinger-Westphal","Motor dorsal y lacrimal"]},{"n":6,"q":"Un paciente con diagnóstico de polineuropatía alcohólica, lo consulta debido a dolor en pies de 9/10, bilateral, urente. Dosaje normal de Vitamina B12. Se encuentra en tratamiento con AINE y pregabalina 75 mg cada 12hs y no cede. Usted decide agregar en primera medida.","o":["Paracetamol","Carbamazepina","Codeina","Ácido tióctico"]},{"n":7,"q":"Un paciente en tratamiento con gabapentin y con antecedente de etilismo hay que evaluar y estar alerta de:","o":["IAM","Toxicidad renal","Toxicidad hepática","Lesión cerebral"]},{"n":8,"q":"Consulta una paciente de 25 años por episodios de cefalea unilateral que describe como pulsátil. Refiere que se acompaña de náuseas y el dolor mejora si está en una habitación oscura. Refiere intensidad de 8 en 10. Niega síntomas neurológicos como destellos visuales asociados a la cefalea. Al examen físico, control de signos vitales dentro de parámetros normales, examen neurológico sin particularidades. Según las características descriptas, ¿Qué tipo de cefalea presenta este paciente?","o":["Tensional.","Migraña SIN aura.","Tipo clúster o en racimos.","Migraña CON aura."]},{"n":9,"q":"Elija qué tipo de vértigo de los a continuación es de origen CENTRAL:","o":["Vértigo postraumático","Cinetosis","Laberintitis","Enfermedad arterial vértebrobasilar"]}]},{"id":"pdf-novas-8","name":"PDF NOVAS · OFTALMOLOGÍA (PENDIENTES DE VALIDACIÓN)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"Pregunta 29 (UAI AGOSTO 2025) Ante un traumatismo, si la pupila esta midriática, que características tiene?","o":["Diámetro entre 2 y 5 mm","Diametro mayor a 5 mm","Diámetro menor a 2 mm.","Ausencia de reflejo pupilar."]},{"n":2,"q":"Un oftalmólogo verifica en una campimetría la presencia de hemianopsia bitemporal. ¿Cuál es el sitio probable de la lesión?","o":["El nervio óptico derecho.","El tracto óptico izquierdo.","La lesión del quiasma óptico.","El labio superior de la cisura calcarina"]}]},{"id":"pdf-novas-9","name":"PDF NOVAS · PEDIATRÍA (PENDIENTES DE VALIDACIÓN)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"pregunta 78 ¿cuál es el incremento de peso esperado diario adecuado según la edad en el primer mes de vida?","o":["niña 12gr/dia. nino 15gr/dia","20-30 gr/día.","40-50 gr/día.","el peso se mantiene constante."]},{"n":2,"q":"pregunta 87 en neonatología, una de las complicaciones prevenibles son las torch. la tétrada de sabin corresponde a:","o":["calcificaciones intracerebrales difusas, convulsiones, coriorretinitis e hidrocefalia. (toxo)","sordera, sordomudez, microcefalia y hepatomegalia.","cardiopatía congénita, microcefalia, sordera y catarata.","ceguera, ictericia, hepatoesplenomegalia y petequias."]},{"n":3,"q":"Bebé de 8 meses que llora mucho cuando la madre se va a trabajar, recomendación?","o":["Dejarle al bebé un objeto transicional.","Evitar despedidas largas y angustiosas.","Asegurarse de que el cuidador sea una persona de confianza y conocida por el bebé.","Todas las anteriores."]},{"n":4,"q":"Recibe en la guardia a un bebe de 5 meses que la madre lo trae porque lo nota agitado. Usted evalúa al paciente: Temperatura axilar 37.3°C, tiraje subcostal e intercostal marcado, sibilancias espiratorias, FR 50, FC 140, saturación de oxigeno a aire ambiente 89. ¿Cuál es la conducta para seguir?","o":["Realiza serie de B2 cada 20 minutos, oxigenoterapia y control posterior.","Realiza serie de B2 y aplica dexametasona IM.","Realiza nebulizacion con salbutamol cada 20 minutos, hidrocortisona endovenosa y control posterior.","Realiza serie B2 cada 20 minutos y meprednisona vía oral."]},{"n":5,"q":"Un niño de 8 años tiene diagnóstico de faringitis estreptocócica por streptest y cultivo de fauces. Teniendo en cuenta la prevención de Fiebre Reumática, ¿cuántos días como máximo, se puede demorar la administración del antibiótico desde el inicio del cuadro?","o":["17 días.","9 días.","2 días.","4 días."]},{"n":6,"q":"Julieta, de 5 años de edad, es traída a su consultorio para control de salud. Su madre le comenta que está preocupada porque durante el sueño la niña presenta ronquidos, pausas respiratorias y despertares por atragantamiento. Durante el día, presenta cefalea matutina, y se la nota somnolienta durante la jornada escolar. Al examen físico usted nota hipertrofia amigdalina, resto sin particularidades. ¿Cuál es el estudio complementario que confirmaría su diagnóstico presuntivo? *","o":["Ecocardiograma.","Polisomnografía Nocturna.","Espirometria.","Endoscopía Respiratoria."]},{"n":7,"q":"Una niña de 7 años es hospitalizada para tratar una neumonía con deshidratación. Ha recibido ceftriaxona EV durante 48 hs. La curva febril ha ido mejorando, pero su estado respiratorio no ha mejorado. El examen físico revela matidez a la percusión en la base del pulmón derecho. ¿Cuáles la complicación más frecuente? *","o":["Empiema.","Neumonía necrotizante.","Fístula broncopleural.","Neumatocele."]},{"n":8,"q":"Respecto a la secuencia de actuación frente a una convulsión activa en un niño de 4 años: *","o":["Valorar vía aérea, oxigenoterapia, posición semisentado, administrar suero glucosado endovenoso.","Valorar vía aérea, oxigenoterapia, posición en decúbito lateral, contención e iniciar terapia anticonvulsivante antes de los primeros 5 minutos.","Valorar vía aérea, oxigenoterapia, contención y administrar una dosis de diazepam intramuscular.","Valorar vía aérea, oxigenoterapia, posición en decúbito lateral, contención, y evaluación primaria general para descartar diagnósticos que requieran actuación inmediata."]},{"n":9,"q":"Niño de 9 años que acude a consulta por fatigabilidad y disnea de esfuerzo progresiva. Al nacer se le había descubierto un soplo cardiaco, pero no acudió a revisiones. En la exploración física la cara y las manos están rosadas, mientras que las extremidades inferiores están cianóticas. ¿Qué anomalía explicaría estos hallazgos? *","o":["Tetralogía de Fallot.","Coartación de aorta.","Ductus arterioso persistente con síndrome de Eisenmenger.","Comunicación interventricular con hipertensión pulmonar."]},{"n":10,"q":"Jacinta tiene 2 meses y su abuela está muy preocupada porque vomita luego de cada toma de biberón. Ud. examina a la niña y el examen físico, el neuromadurativo y la curva pondoestatural son normales para la edad. Ud tranquiliza a la familia y les explica que se trata de un proceso fisiológico normal. La abuela le consulta, ¿hasta cuándo es normal?","o":["Alcanza su punto culminante a los 8 meses y desaparece entre los 24 y 36 meses.","Alcanza su punto culminante a los 2 meses y desaparece entre los 12 y 24 meses.","Alcanza su punto culminante a los 6 meses y desaparece entre los 24 y 36 meses.","Alcanza su punto culminante a los 4 meses y desaparece entre los 12 y 24 meses."]},{"n":11,"q":"Consulta a la guardia una paciente de 15 años, primigesta, cursando un embarazo de 28 semanas de edad gestacional, adjuntando una ecografía obstétrica que informa Hidrops Faetalis. Se solicita un Doppler Fetal que resulta compatible con anemia fetal severa. Al interrogatorio la joven refiere no tener antecedentes de importancia, pero comenta que sus hermanos tuvieron hace unos meses “una gripe con erupción en la cara que se curó sola”. En base a estos datos, ¿de qué infección exantemática puede tratarse? *","o":["Escarlatina.","Quinta Enfermedad.","Varicela.","Sarampión."]},{"n":12,"q":"Un niño de 7 años sufre una caída sobre el brazo izquierdo produciéndose una fractura en tercer medio de da clavícula desplazada. ¿Cuál sería el tratamiento a seguir?","o":["Vendaje en 8.","Vendaje de yeso","No necesita tto","Férula de abducción"]},{"n":13,"q":"Ignacio de 1 mes de vida es hijo de madre HIV positiva, trae un resultado negativo de ADN proviral reacción en cadena de polimerasa (PCR). Según el manual de Atención Integral de niños, niñas y adolescentes con HIV (2012) ¿En qué momento se debe realizar el próximo estudio de HIV en este paciente?","o":["ADN PCR a los 2 meses.","Serología de HIV a los 6 meses","Serología de HIV a los 10 meses","ADN PCR a los 18 meses"]},{"n":14,"q":"Ud atiende un paciente pediátrico con NAC que pesa 12kg, Le indica amoxicilina 100mg/kg/día (3 tomas), Si receta amoxicilina en suspensión de 500mg/5ml, ¿Que volumen le indica a la madre que le administre?","o":["4 ml cada 8hs.","5 ml cada 8 horas","4 ml cada 6 horas","5 ml cada 6 horas"]},{"n":15,"q":"María de 10 años es traída a control de salud. su mamá está preocupada porque “es muy bajita”. usted constata baja talla para la edad, cuello corto, aumento de la distancia intermamilar, nevos hiperpigmentados. no inició aún su desarrollo puberal. ¿cuál es el diagnóstico más probable?","o":["Déficit de hormona de crecimiento.","Enfermedad celíaca.","Síndrome de noonan.","Síndrome de turner."]},{"n":16,"q":"un adolecente en apariencia sano consulta para control. el examen de los genitales revela estadio 5 de desarrollo puberal y un tumor no doloroso en el escroto izquierdo que se extiende desde el canal inguinal hasta el polo superior del testículo. el tumor disminuye de tamaño cuando el joven se acuesta. ¿cuál es el diagnóstico, más probable?","o":["Hidrocele","Tumor testicular","Varicocele","Quiste de morgagni"]},{"n":17,"q":"carmen y pedro tienen 3 hijos, enrique de 5 anos, isabel de 4 y raquel de 1. recientemente han notado que enrique tiene ciertos problemas para subir las escaleras y se cansa mucho cuando corre. despues de unas pruebas médicas, le han diagnosticado una enfermedad genética llamada, distrófica muscular de Duchennne. señale la alternativa correcta sobre el tipo probable de esta enfermedad.","o":["La madre es la que le ha transmitido la enfermedad","El padre es el que ha transmitido la enfermedad","Ambos padres le han transmitido la enfermedad","Si tuvieran otro váron tendria un 100% de tener la posibilidad de tener la enfermedad"]},{"n":18,"q":"¿Cuándo se aconseja intervenir quirúrgicamente la hernia umbilical infantil?","o":["Se debe intervenir cuanto antes para evitar el riesgo de estrangulación.","A partir de los 3 o 4 años de vida, al ser frecuente su cierre espontáneo antes de esa edad.","Con el fin de utilizar prótesis en la cirugía, se recomienda esperar a que el paciente sea mayor.","Si el niño presentara vómitos durante los accesos febriles."]},{"n":19,"q":"Cuál es el diagnóstico más probable de un lactante de 6 meses que presenta eritema en regiones glútea, genital y superficies convexas de los muslos, dejando libre el fondo de los pliegues? (único 2020)","o":["Psoriasis del pañal.","Dermatitis del pañal.","Dermatitis seborreica.","Impétigo."]},{"n":20,"q":"Usted recibe a un niño de 8 meses que consulta por 4 vez en el servicio durante este mes. Lo evalúa y se encuentra con una enfermedad recurrente que no puede explicar, los resultados de sus investigaciones no concuerdan con la salud general del niño, los síntomas no se presentan cuando el progenitor no está, su cuidador principal no quiere dejar nunca el niño solo en el hospital y no muestra preocupación por su niño como el personal del hospital. ¿En qué piensa frente a esta situación?","o":["Trastornos de comprensión","Síndrome de Munchausen","Mal trato infantil","Iatrogenia"]}]},{"id":"pdf-novas-10","name":"PDF NOVAS · NEFROLOGÍA (PENDIENTES DE VALIDACIÓN)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"en una nefrona, el 60% del cloruro de sódio es reabsorvido en?","o":["Túbulo proximal","Rama descendente del asa del henle","Rama ascendente del asa del henle","Túbulo contorneado distal"]},{"n":2,"q":"mujer de 68 años, que es diagnosticada de una tbc pulmonar. se instauro tto con isoniacida, rifampsina y etambutol. a los 12 días de iniciado el tratamiento consulta por fiebre de 38ºc, exantema cutâneo, adenopatias, artralgia, dolor lumbar, oliguria y eosinofilia con deterioro agudo de la función renal. en el examen de orina se identificó hematúria, leucocituria con eosinofiluria. en la tincion de wright e proteinuira en rango no nefrótico (1,2g/diários) con estos datos el diagnóstico más probable es?","o":["Necrosis tubular aguda por nefrotoxidad a fármacos","Enfermed ateroembolica","Oclusión trombótica de la artéria renal principal","Nefritis túbulointersticial aguda"]},{"n":3,"q":"hombre de 60 años que acude a urgencia por presentar hematuria macroscópica asintomática. en que patología deberíamos pensar en primero lugar.","o":["Hiperplasia benigna de próstata","Carcinoma de próstata","Carcinoma de vesical","Litiasis renal"]},{"n":4,"q":"hombre de 78 años, al que se realizó un cateterismo cardíaco con revascularización de arteria coronaria derecha hace 3 semanas y que consulta por náuseas y vómitos por 3 días de evolución. presenta ta: 185/85 mmhg y lesiones purpúreas en los dedos de ambos los pies. en la analítica se observa: urea: 230, creatinina: 5,8. cuál es el dx más probable?","o":["Hipertensión arterial maligna","Necrosis tubular aguda por contraste","Insuficiencia renal rápidamente progresiva","Enfermedad ateroembolica renal"]},{"n":5,"q":"Un paciente de 18 años con antecedentes de faringitis eritematoso exudativa 15 días antes, lo consulta por emisión de orinas color rojizo. Presenta edema facial, TA: 170/100, diuresis 400ml/ 24 hs y orina completa con 10 hematíes dismórficos/campo. Urea y creatinina normales.","o":["Su diagnóstico presuntivo es nefropatía por IgA (enfermedad de Berger) por la presencia de hematuria glomerular en un paciente asintomático con antecedentes de cuadro viral reciente.","Teniendo en cuenta el grupo etario de este paciente, considera que deben descartarse causas de hematuria no glomerular.","Ud. sospecha en primera instancia causas secundarias de enfermedad glomerular.","Tratándose de un paciente joven con antecedente de infección de vía aérea superior, ud sospecha síndrome nefrítico secundario a GNF postestreptocócica."]}]},{"id":"pdf-novas-11","name":"PDF NOVAS · NEUMONOLOGÍA (PENDIENTES DE VALIDACIÓN)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"pregunta 43 (UAI AGOSTO 2025) una mujer de 68 años consulta por fiebre de 38,7°c, los con expectoración amarilla y disnea progresiva desde hace tres días. es hipertensa y diabética, controlada con metformina. saturación de o2 al ingreso: 95% en aire ambiente. al examen se auscultan crepitantes en base pulmonar derecha. re de tórax: consolidación en lóbulo inferior derecho. se encuentra hemodinámicamente estable. ¿cuál es el tratamiento antibiótico ambulatorio más apropiado?","o":["claritromicina oral.","levofloxacina oral.","amoxicilina-ácido clavulánico","ceftriaxona im"]},{"n":2,"q":"¿Cuál de las siguientes opciones permite realizar un diagnóstico de sinusitis aguda bacteriana?","o":["Un cuadro de 5 días de evolución acompañado de cefalea frontal, congestión nasal, malestar general.","Un cuadro que persiste por 10 días sin evidencia de mejoría, con fiebre y dolor facial","Un cuadro que persiste 8 días con dolor facial","Ninguna de las alternativas"]},{"n":3,"q":"Una paciente de 23 años consulta por presentar tos de dos meses de evolución, sudoración nocturna y fiebre no cuantificada. Desde la última semana presenta falta de aire que la obliga a detenerse al caminar 200 metros. Al examen físico se encuentra adelgazada y a la auscultación pulmonar presenta hipoventilación global. Refiere vivir con 4 hermanos en una pieza en condiciones de hacinamiento. Según su sospecha diagnóstica, ¿cuál es la conducta más adecuada?","o":["Solicitar baciloscopía de esputo, radiografía tórax y hemograma.","Realizar fibrobroncoscopía con lavado broncoalveolar y esputo para BAAR.","Solicitar baciloscopía de esputo y tomografía de tórax con contraste endovenoso.","Realizar fibrobroncoscopía y PPD"]},{"n":4,"q":"una paciente intervenida hace 2 años de un tumor epidermoide del pulmón derecho y diag. de metástasis ósea y hepática hace 2 meses acude a la guardia por notar hinchazón de la cara y del cuello, tos seca y disnea progresiva a mínimos esfuerzos. en la exploración se evidencia edema en esclavina y en la radiología de tórax ensanchamiento del mediastino. indique la conducta más adecuada.","o":["Realizar rnm y biopsia de la lesión antes de tomar cualquier decisión","Realizar rnm para complementar el estudio e iniciar tto radioterapeutico urgente","Realizar tac de tórax e iniciar tto con esteroides a alta dosis y radioterapia urgente","Realizar un examen radiológico para completar los estudios que puede ser una rnm o un tac de tórax"]},{"n":5,"q":"recibe en la guardia un paciente con diagnóstico prévio de epoc. refiere aumento de la disnea habitual, aumento de la expectoración y cambio en las características del esputo. usted piensa en una reagudización de su enfermedad de base. cual de las seguientes no corresponde a una opción terapéutica apropiada.","o":["o2 a alto fluxo (mascara al 50%)","Corticoides sistêmicos","Antibioticos","Nebulizaciones con bromuro de ipratopio"]},{"n":6,"q":"en la evaluación de tep se utilizan los seguientes estúdios complementários. excepto:","o":["Espirometria","Dimero-d","Centellograma v/q","Ecocardiograma"]},{"n":7,"q":"una mujer de 63 años, ingressa en el hospital para tto de un ca de cuello. presenta un dolor pleurítico en hemitórax izquierdo y disnea de comienzo brusco. a la exploración la enferma esta taquipineica, con signos de mala perfusión periférica, ta sistólica de 70mmgh.un ecg muestra la inversión de la onda t, de v1-v4. cuál es la conducta clínica más adecuada para realizar la continuación?","o":["Se debe solicitar determinación de dimero-d, para confirmar o descartar el dx de embolia del pulmón","Hay alta sospecha de embolia de pulmón y si debe iniciar tto con heparina con bajo peso molecular, sin realizar más estúdios","Existe de alta sospecha de embolia de pulmón masiva y se debe realizar angiotc para confirmar y valorar el tto fibrinolítico","Se debe solicitar determinación de ntprobnp y troponinas y conocer los resultados antes de realizar un nuevo procedimiento diagnósticos."]},{"n":8,"q":"en un paciente neutropenico con déficit de la inmunidad celular (cd4 bajos ppd hipo o enérgicas) y un infiltrado pulmonar difuso en la rx de tórax. cual sería tu primer dx.","o":["Infección por bacilos gran negativos","Aspergiloma","Tuberculosis","Linfangites carcinomatosa"]},{"n":9,"q":"una mujer de 21 años, ingresa la guardia traída en ambulancia por crisis asmática, luego de haber estado disneica, casi toda la noche. fue tto agonistas b2 durante el traslado. al ingreso se coloca vía periférica, o2 e monitor. esta diaforética, excitada e se quita la máscara de 02 repetidamente. no puede hablar. presenta tórax silente a auscultación pulmonar. cuál es la conducta inmediata a seguir:","o":["Medir gases en sangre arterial y luego iniciar tto con nebulización con agonistas b2 y corticoides sistémicos","Iniciar tto con nebulizaciones con agonista b2 continuos","Realizar intubación endotraqueal","Administrar corticoides sistémicos"]},{"n":10,"q":"una mujer 58 años acude a la consulta por disnea de medianos esfuerzos, debilidad muscular en extremidades superiores y disfagia a sólidos de 3 meses de evolución. a la exploración física, se objetiva pérdida de fuerza en extremidades superiores con sensibilidad conservada. la auscultación pulmonar muestra hipofonesis generalizada. se realiza un rx de tórax en la que se aprecian un de los pulmones poco inspirado y atelectasias laminares en las bases pulmonares. la gasometría muestra ph 7,39 pco2 48, po2: 63 hco3: 28 sato2: 93%. la combinación de mecanismos fisiológicos que explica esta gasometría es?","o":["Disminución de la fio2 (fracción inspirada de o2) y alteración de la difusión","Alteración de la difusión e trastorno de la relación v/q","Hipoventilación alveolar y disminución de la fio2","Trastorno de la relación v/q e hipoventilación alveolar"]},{"n":11,"q":"la primera alteración respiratoria demostrable en fumadores, reversible a suspender el habito de fumar es?","o":["Tos","Expectoración","Obstrucción de las vías aéreas distales","Disminución de movimiento ciliar"]},{"n":12,"q":"ante un paciente con una otitis externa difusa, cual tratamiento inicial?","o":["Quirúrgico","Antibiótico y analgésico ambos vía oral","Limpieza del CAER, atb tópico más analgésico orales","Antibiótico tópicos"]},{"n":13,"q":"La práctica de una radiografía posteroanterior de tórax en espiración forzada es de gran utilidad para el diagnóstico de:","o":["Derrame pleural loculado.","Neumotórax mínimo.","Hemotórax.","Atelectasia pulmonar"]},{"n":14,"q":"Un paciente tiene un volumen espiratorio en el 1er segundo VEF1= 76%, después de broncodilatadores y el volumen espiratorio/capacidad vital inspiratoria = 104%. El patrón espirométrico corresponde a:","o":["Obstrucción moderada","Obstrucción severa","No tiene obstrucción","Podemos concluir que tiene una fibrosis pulmonar"]},{"n":15,"q":"A un paciente asmático se le realiza una espirometria durante una crisis de espasmo bronquial leve. ¿Qué elementos de este estudio Ud jerarquizaría para evaluar la vía aérea superior?","o":["Capacidad vital forzada.","Flujo espiratorio forzado en el primer segundo.","Volumen de reserva espiratorio.","Volumen residual."]},{"n":16,"q":"Paciente de 72 años, con antecedente de HTA e ICC, medicado con furosemida, enalapril y carvedilol, lo consulta por disnea súbita. Sin dolor precordial ni fiebre. Usted lo ausculta y presenta rales crepitantes en marea ascendente, y el MV se encuentra disminuido. A nivel cardiovascular los ruidos están hipofonéticos sin soplos. No hay hepatomegalia, edemas en MMII ++, con fóvea. Usted decide internar al paciente con sospecha diagnóstica de:","o":["IAM","Edema agudo de pulmón","Endocarditis","NAC"]},{"n":17,"q":"Se encuentra con un paciente de 18 años sin antecedentes de relevancia ni alergias medicamentosas referidas, que por presentar un cuadro de faringitis aguda se cultivó, ya que se había descartado previamente COVID19 y dicho cultivo dió positivo para Estreptococo Beta Hemolítico grupo A (EBHGA). ¿Cuál es su primera elección de antibiótico?","o":["Penicilina V 500 mg c/ 12 hs (800.000 UI) vía oral durante 10 días.","Eritromicina 500 mg c/ 8 hs vía oral durante 10 días. (alergia a penicilina).","Penicilina benzatinica 1.200.000 UI IM en dosis única.","Amoxicilina 500 mg c/ 8 hs vía oral por 5 días (10 dias el correcto)"]},{"n":18,"q":"¿Qué parámetros se tienen en cuenta en el Score CRB-65 para definir la conducta de un paciente con Neumonía aguda de la comunidad?","o":["Confusión, Frecuencia respiratoria > 30 rpm, TAS < 90 mmHg o TAD ≤ 60 mmHg, edad > 65 años.","Confusión, Frecuencia cardiaca > 100 lpm, TAS < 90 mmHg o TAD ≤ 60 mmHg, edad > 65 años.","Estertores crepitantes, Frecuencia respiratoria > 30 rpm, saturación de oxígeno < 95% (aire ambiente), edad > 65 años.","Creatinina plasmática, Frecuencia cardiaca > 100 lpm, TAS < 90 mmHg o TAD ≤ 60 mmHg, edad > 65 años."]}]},{"id":"pdf-novas-12","name":"PDF NOVAS · REUMATOLOGÍA (PENDIENTES DE VALIDACIÓN)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"Una mujer de 36 años, con diagnóstico de Artritis Reumatoide, consulta al médico por dolor y tumefacción en manos, muñecas y rodillas. ¿Cuál de los siguientes tratamientos retardará la progresión de la enfermedad?","o":["Metrotexato.","Glucocorticoides sistémicos.","Antiinflamatorios no esteroideos.","Glucocorticoides intraarticulares"]},{"n":2,"q":"una enferma de 55 años presenta dolor intenso en columna torácica sin trauma o esfuerzo violento previo. al practicar radiografías se observan aplastamientos a nivel t5 y t9. ¿cuál será la causa más frecuente de esta lesión?:","o":["Tuberculosis vertebral","Metástasis","Enfermedad de paget","Osteoblastoma"]},{"n":3,"q":"la claudicación intermitente de los gemelos está causada más frecuentemente por enfermedades oclusivas en la arteria?","o":["Ilíaca externa","Femoral superficial","Femoral profunda","Tibial posterior."]}]},{"id":"pdf-novas-13","name":"PDF NOVAS · TOXICOLOGÍA (PENDIENTES DE VALIDACIÓN)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"Se sospecha que un adolescente de 15 años consume drogas. Cuál de las siguientes sustancias es la que no sería detectada en una pesquisa toxicológica en orina de rutina por su escasa persistencia. (UBA 2016)","o":["Marihuana","Cocaína","Heroína","Alcohol"]},{"n":2,"q":"¿Cuáles son las medidas a implementar en un paciente que presenta un envenenamiento ofídico por Yarará?","o":["Colocar lazo en sitio de la mordedura para evitar la circulación del veneno.","Retirar anillos, pulseras, cadenas, tobilleras y zapatos que puedan comprometer la circulación sanguínea.","colocar analgésicos de forma intramuscular.","Inyectar antiveneno en el sitio de la mordedura ya que neutralizará más rápido el veneno."]},{"n":3,"q":"Cual de estos medicamentos abajo salió del mercado","o":["Ranitidina","Omeprazol","Pantoprazol","Esomeprazol"]}]}]);
